const toast=document.querySelector('[role="status"]');let timer;function notify(message){if(!toast)return;toast.textContent=message;clearTimeout(timer);timer=setTimeout(()=>toast.textContent='',3500)}document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.copy);notify('Copied '+button.dataset.copy)}catch{notify(button.dataset.copy)}}));document.querySelectorAll('[data-jump]').forEach(button=>button.addEventListener('click',()=>document.querySelector(button.dataset.jump)?.scrollIntoView({behavior:'smooth'})));const note=document.querySelector('#note');try{const saved=localStorage.getItem('scribblit-note');if(saved!==null)note.value=saved}catch{}document.querySelector('#save-note').addEventListener('click',()=>{try{localStorage.setItem('scribblit-note',note.value);document.querySelector('#save-status').textContent='Saved just now';notify('Your note is saved on this device.')}catch{notify('This browser could not save the note. Please copy your text.')}});document.querySelectorAll('[data-tone]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('.notebook').style.background={blue:'#f2faff',white:'#ffffff',green:'#f2fff0'}[b.dataset.tone];document.querySelector('#note-demo').scrollIntoView({behavior:'smooth'})}));document.querySelectorAll('[data-billing]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-billing]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});const yearly=b.dataset.billing==='annual';document.querySelector('[data-price="starter"]').textContent=yearly?'$15.20':'$19';document.querySelector('[data-price="pro"]').textContent=yearly?'$47.20':'$59';document.querySelector('.pricing-note').textContent=yearly?'Billed yearly. Illustrative template pricing; no payment is collected.':'Illustrative template pricing. No payment is collected.'}));document.querySelector('[data-year]').textContent=new Date().getFullYear();